async () => {
  const found = await connecta.search({ query: "list zones DNS records", safety: "readOnly", includeSchemas: "compact", limit: 20 });
  const ts = found.tools || [];
  const zoneTool = ts.find(t => /list.*zone|zone.*list/i.test((t.address||"")+" "+(t.name||"")+" "+(t.description||"")));
  const recordTool = ts.find(t => /list.*record|record.*list/i.test((t.address||"")+" "+(t.name||"")+" "+(t.description||"")));
  if (!zoneTool || !recordTool) throw new Error("Required Edge DNS tools not found: " + ts.map(t=>t.address).join(", "));
  const descs = await connecta.describe({ addresses: [zoneTool.address, recordTool.address] });
  const arr = Array.isArray(descs) ? descs : (descs.tools || descs.results || [descs]);
  const zd = arr.find(x => x.address === zoneTool.address) || zoneTool;
  const rd = arr.find(x => x.address === recordTool.address) || recordTool;
  const keys = x => x.inputKeys || (x.inputSchema && x.inputSchema.properties ? Object.keys(x.inputSchema.properties) : []);
  const makeArgs = (ks, zoneId) => {
    const a = {};
    for (const k of ks) {
      const n = k.toLowerCase();
      if (/account/.test(n)) a[k] = "acct_eval_7";
      else if (zoneId !== undefined && (/zone.*id/.test(n) || n === "zone")) a[k] = zoneId;
      else if (/type|record.*type/.test(n)) a[k] = "TXT";
    }
    return a;
  };
  const zoneResult = await connecta.call(zoneTool.address, makeArgs(keys(zd)));
  const walk = (v) => {
    if (!v || typeof v !== "object") return undefined;
    if (!Array.isArray(v)) {
      for (const [k,val] of Object.entries(v)) if (/^(id|zone_id|zoneId)$/.test(k) && typeof val === "string") return val;
    }
    for (const val of Object.values(v)) { const x = walk(val); if (x !== undefined) return x; }
  };
  const zoneId = walk(zoneResult);
  if (!zoneId) throw new Error("No zone id found in zone-list result");
  const recordResult = await connecta.call(recordTool.address, makeArgs(keys(rd), zoneId));
  return [zoneResult, recordResult];
}

